import styles from './SummaryCard.module.css';
import useFinancialData from './useFinancialData';

const SummaryCard = () => {
  // Estado inicial (si no hay datos en localStorage, usa estos valores)
  const initialData = {
    totalIncome: 0,
    totalExpenses: 0,
    balance: 0,
    currentBalance: 0,
  };

  const [financialData, setFinancialData] = useFinancialData(initialData);

  // Ejemplo: Función para actualizar ingresos
  const updateIncome = (amount) => {
    setFinancialData({
      ...financialData,
      totalIncome: financialData.totalIncome + amount,
      balance: financialData.totalIncome + amount - financialData.totalExpenses,
      currentBalance: financialData.currentBalance + amount,
    });
  };

  // Ejemplo: Función para actualizar gastos
  const updateExpenses = (amount) => {
    setFinancialData({
      ...financialData,
      totalExpenses: financialData.totalExpenses + amount,
      balance: financialData.totalIncome - (financialData.totalExpenses + amount),
      currentBalance: financialData.currentBalance - amount,
    });
  };

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${financialData.totalIncome}</p>
        <button onClick={() => updateIncome(100)}>+ $100</button>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${financialData.totalExpenses}</p>
        <button onClick={() => updateExpenses(50)}>+ $50</button>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${financialData.balance}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${financialData.currentBalance}</p>
      </div>
    </div>
  );
};

export default SummaryCard;
